{public array $target=['id'=>7,'public_id'=>'USER-7','status'=>'active','openid'=>'openid-7'];public array $saved=[];public int $revoked=0;public function usersPage(string $search,string $riskFilter,int $page,int $perPage,bool $includeDemo):array{return ['rows'=>[],'total'=>0,'page'=>$page,'pages'=>1,'per_page'=>$perPage,'risk_stats'=>['attention'=>0,'restricted'=>0]];}public function membershipTarget(int $userId,string $appId):?array{return $userId===7?$this->target:null;}public function saveMembershipGrant(int $userId,int $adminId,string $cardId,string $proofHmac,string $expiresAt,string $activationCode):int{$this->saved=compact('userId','adminId','cardId','proofHmac','expiresAt','activationCode');return 99;}public function revokeMembership(int $userId,int $adminId):int{$this->revoked++;return 1;}public function merchantsPage(string $search,string $status,int $page,int $perPage):array{return ['rows'=>[],'total'=>0,'page'=>$page,'pages'=>1,'per_page'=>$perPage,'stats'=>[]];}public function reviewMerchant(int $merchantId,string $decision,string $reason,int $adminId):void{}}
final class FakeWorkerCloudGateway implements WorkerCloudGateway
{public array $actions=[];private string $secret;public function __construct(string $secret){$this->secret=$secret;}public function invoke(string $action,array $payload=[]):array{$this->actions[]=$action;if($action==='server.membershipGrant'){$end='2027-12-31';$card='CARD-7';$openid=(string)$payload['target_openid'];return ['card_id'=>$card,'vip_end_time'=>$end,'proof_hmac'=>hash_hmac('sha256','membership|'.$card.'|'.$openid.'|'.$end,$this->secret)];}if($action==='server.membershipStatus')return ['member_valid'=>true,'member_bound'=>true,'vip_end_time'=>'2027-12-31'];if($action==='server.membershipRevoke')return ['ok'=>true];return [];}}
final class FakeSettingsProvider implements SettingsProvider
{private string $secret;public function __construct(string $secret){$this->secret=$secret;}public function get(string $key,$default=null){if($key==='wechat.miniapp_appid')return 'wx-test';if($key==='wechat.worker_admin_secret')return $this->secret;return $default;}public function bool(string $key,bool $default=false):bool{return $key==='demo.data_enabled'?true:$default;}public function int(string $key,int $default=0):int{return $default;}}
