$owners=['users'=>'UserMerchantAdminModule','users.membership.grant'=>'UserMerchantAdminModule','users.membership.revoke'=>'UserMerchantAdminModule','merchants'=>'UserMerchantAdminModule','merchants.review'=>'UserMerchantAdminModule','worker-credentials'=>'RealNameAdminModule','workers.realname.review'=>'RealNameAdminModule','workers.realname.update'=>'RealNameAdminModule','workers.realname.revoke'=>'RealNameAdminModule','collection-codes.review'=>'RealNameAdminModule'];foreach($owners as $route=>$owner){$source=$owner==='UserMerchantAdminModule'?$userModule:$realNameModule;$assert(strpos($source,"'{$route}'")!==false,'formal owner missing '.$route);$assert(strpos($legacy,"'{$route}'")!==false,'anti-fallback missing '.$route);}
